270→// ── Scope custom CSS for admin preview — prefix selectors with #wid ─────────
271→function scopeAdminCss(rawCss: string | null | undefined, wid: string): string {
272→  if (!rawCss) return "";
273→  const css = rawCss.replace(/<\/style>/gi, "");
274→  let result = "";
275→  let remaining = css;
276→  while (remaining.length > 0) {
277→    const openBrace = remaining.indexOf("{");
278→    if (openBrace === -1) break;
279→    const closeBrace = remaining.indexOf("}", openBrace);
280→    if (closeBrace === -1) break;
281→    const selector = remaining.substring(0, openBrace).trim();
282→    const body = remaining.substring(openBrace + 1, closeBrace);
283→    remaining = remaining.substring(closeBrace + 1);
284→    if (selector.startsWith("@")) {
285→      result += selector + "{" + body + "}";
286→    } else if (selector) {
287→      const prefixed = selector.split(",").map(s => {
288→        s = s.trim();
289→        return s ? "#" + wid + " " + s : "";
290→      }).filter(Boolean).join(", ");
291→      result += prefixed + " {" + body + "}";
292→    }
293→  }
294→  return result;
295→}
